#include <stdio.h>
int main(void) {
    int n = 10, i, eleman = 0, govde = 0;
    double a = 2.0, x[10], y[10];
    for (i = 0; i < n; i++) { x[i] = i; y[i] = 1.0; }
    for (i = 0; i + 3 < n; i += 4) {      /* 4'lu acilmis govde */
        y[i]     = a * x[i]     + y[i];
        y[i + 1] = a * x[i + 1] + y[i + 1];
        y[i + 2] = a * x[i + 2] + y[i + 2];
        y[i + 3] = a * x[i + 3] + y[i + 3];
        govde++; eleman += 4;
    }
    for (; i < n; i++) { y[i] = a * x[i] + y[i]; eleman++; }  /* artik dongusu */
    printf("govde=%d artik=%d eleman=%d\n", govde, n - 4 * govde, eleman);
    printf("y[0]=%.1f y[9]=%.1f\n", y[0], y[9]);
    return 0;
}

#include <stdio.h>
#define N 64
#define LINE 16   /* 16 int = 64 bayt blok */
#define SETS 8    /* 8 kumeli, dogrudan eslemeli kucuk onbellek */

static int etiket[SETS], gecerli[SETS];
static long isabetsiz;

static void sifirla(void) {
    for (int i = 0; i < SETS; i++) { gecerli[i] = 0; etiket[i] = 0; }
    isabetsiz = 0;
}

static void eris(long dizin) {          /* dizin: int cinsinden ofset */
    long blok = dizin / LINE;
    int kume = (int)(blok % SETS);
    int t = (int)(blok / SETS);
    if (!gecerli[kume] || etiket[kume] != t) {
        isabetsiz++; gecerli[kume] = 1; etiket[kume] = t;
    }
}

int main(void) {
    sifirla();
    for (int i = 0; i < N; i++)            /* satir sirali: a[i][j] */
        for (int j = 0; j < N; j++) eris((long)i * N + j);
    long satir = isabetsiz;

    sifirla();
    for (int j = 0; j < N; j++)            /* sutun sirali: a[i][j], i hizli */
        for (int i = 0; i < N; i++) eris((long)i * N + j);
    long sutun = isabetsiz;

    printf("satir sirali isabetsizlik = %ld\n", satir);
    printf("sutun sirali isabetsizlik = %ld\n", sutun);
    printf("oran = %ld\n", sutun / satir);
    return 0;
}

#include <stdio.h>
#define T 4          /* cekirdek sayisi */
#define N 1000       /* cekirdek basina yazma */
#define LINE 64      /* onbellek satiri, bayt */

static int sahip[8];             /* satir -> sahip cekirdek, -1 = sahipsiz */
static long devir, gecersiz;

static void sifirla(void) {
    for (int i = 0; i < 8; i++) sahip[i] = -1;
    devir = 0; gecersiz = 0;
}

static void yaz(long adres, int cekirdek) {
    int satir = (int)(adres / LINE);
    if (sahip[satir] != cekirdek) {      /* ozel sahiplik gerekiyor */
        devir++;
        if (sahip[satir] != -1) gecersiz++;   /* onceki sahip gecersizlenir */
        sahip[satir] = cekirdek;
    }
}

int main(void) {
    long dolgusuz[T] = { 0, 4, 8, 12 };          /* hepsi ayni 64 baytlik satirda */
    long dolgulu[T]  = { 0, 64, 128, 192 };      /* her biri ayri satirda */

    sifirla();
    for (int i = 0; i < N; i++)
        for (int t = 0; t < T; t++) yaz(dolgusuz[t], t);
    printf("dolgusuz: devir=%ld gecersizlestirme=%ld\n", devir, gecersiz);
    long d1 = devir;

    sifirla();
    for (int i = 0; i < N; i++)
        for (int t = 0; t < T; t++) yaz(dolgulu[t], t);
    printf("dolgulu : devir=%ld gecersizlestirme=%ld\n", devir, gecersiz);
    printf("oran = %ld\n", d1 / devir);
    return 0;
}
